/**
 * Parser for the INPUT_*.html files generated by QE's helpdoc tool.
 *
 * Strategy: transform the original markup into clean semantic HTML
 * (sections / articles / definition lists) while keeping every piece of
 * content. Unknown constructs are unwrapped rather than dropped, so nothing
 * from the source disappears silently. Structured metadata (sections,
 * variables, links) is extracted from the transformed DOM.
 */
import type { CheerioAPI, Cheerio } from 'cheerio';
import type { AnyNode, Element } from 'domhandler';
import type { InputDoc, InputSection, InputSectionKind, Variable } from '../../src/types/docs.ts';
import {
  load, squash, stripTags, slugify, IdRegistry, flowPre, sanitize, decorateExternalLinks,
  firstSentence, tidyHeading, escapeHtml, blockText,
} from './util.ts';

export interface RawLink {
  /** canonical id of the variable containing the link (undefined if outside any variable) */
  fromVar?: string;
  kind: 'ref' | 'see';
  /** in-document target id (already resolved through aliases) */
  localTarget?: string;
  /** cross-document target */
  xdoc?: string;
  xfrag?: string;
}

export interface ParsedInput {
  doc: InputDoc;
  links: RawLink[];
  varText: Record<string, string>;
  sectionText: Record<string, string>;
  introText: string;
  warnings: string[];
}

const ID_RE = /^idm?\d+$/;
const XDOC_RE = /(?:^|\/Doc\/|^\.\/)(INPUT_[A-Za-z0-9_]+)\.(?:html|txt|xml)(?:#(.*))?$/;

export function styleHas(el: Cheerio<Element>, needle: string): boolean {
  return (el.attr('style') || '').replace(/\s+/g, ' ').toLowerCase().includes(needle.toLowerCase());
}

function rowsOf(_$: CheerioAPI, table: Cheerio<Element>): Cheerio<Element> {
  const body = table.children('tbody');
  return (body.length ? body.children('tr') : table.children('tr')) as Cheerio<Element>;
}

/** Anchors (<a name>) immediately preceding an element, in document order. */
function precedingAnchors($: CheerioAPI, el: Cheerio<Element>): Cheerio<Element>[] {
  const out: Cheerio<Element>[] = [];
  let node = el[0].prev;
  while (node) {
    if (node.type === 'text') {
      if ((node as unknown as { data: string }).data.trim()) break;
    } else if (node.type === 'tag' && (node as Element).tagName === 'a' && (node as Element).attribs.name !== undefined && !$(node).text().trim()) {
      out.unshift($(node as Element));
    } else break;
    node = node.prev;
  }
  return out;
}

export function buildVarArticle(o: {
  id: string;
  display: string;
  nameHtml?: string;
  type?: string;
  status?: string;
  meta: { label: string; html: string }[];
  descHtml: string;
  flags?: boolean;
}): string {
  const badges = [
    o.type ? `<span class="qe-type" title="Fortran type">${escapeHtml(o.type)}</span>` : '',
    o.status ? `<span class="qe-status">${escapeHtml(o.status)}</span>` : '',
  ].filter(Boolean).join(' ');
  const meta = o.meta.length
    ? `<dl class="qe-meta">${o.meta.map((m) => `<div class="qe-meta-row qe-meta-${slugify(m.label)}"><dt>${escapeHtml(m.label)}</dt><dd>${m.html}</dd></div>`).join('')}</dl>`
    : '';
  const cls = o.flags ? 'qe-var qe-flags' : 'qe-var';
  return (
    `<article class="${cls}" id="${o.id}" data-var="${o.id}">` +
    `<header class="qe-var-head"><h3 class="qe-var-name"><a class="qe-self" href="#${o.id}">${o.nameHtml ?? escapeHtml(o.display)}</a></h3> ${badges} ` +
    `<span class="qe-var-tools" data-var="${o.id}"></span></header>` +
    meta +
    `<div class="qe-desc">${o.descHtml}</div>` +
    `</article>`
  );
}

export function parseHelpdocHtml(html: string, file: string, docId: string): ParsedInput {
  const warnings: string[] = [];
  const $ = load(html);

  /* ---- header ---- */
  const headerText = squash($('body > table').first().find('h2').first().text());
  const hm = headerText.match(/Program:\s*([^/]+?)\s*\/\s*(.+?)\s*(?:\(version:\s*([^)]+)\))?$/);
  const parts = hm ? hm[2].split('/').map((s) => s.trim()) : [];
  const program = hm ? hm[1].trim() : docId;
  const pkg = parts[0] && parts[0] !== 'Quantum ESPRESSO' ? parts[0] : undefined;
  const version = hm?.[3]?.trim();

  const outer = $('body > table').first();
  const main = rowsOf($, outer).eq(1).children('td').first();
  if (!main.length) throw new Error(`${file}: unexpected structure (no main cell)`);

  const ids = new IdRegistry(['top', 'content', 'main']);
  const aliases: Record<string, string> = {};

  /* ---- remove TOC and back-to-top links ---- */
  main.children('blockquote').each((_, b) => {
    if (/^TABLE OF CONTENTS$/i.test(squash($(b).children('h3').first().text()))) $(b).remove();
  });
  main.find('div').each((_, d) => {
    if (squash($(d).text()) === '[Back to Top]') $(d).remove();
  });
  main.find('a[name="__top__"]').remove();

  /* ---- variables ---- */
  const varTables = main.find('table').filter((_, t) => styleHas($(t), '#b5b500')).toArray();
  for (const t of varTables) {
    const table = $(t);
    const rows = rowsOf($, table);
    const r0 = rows.eq(0).children();
    const flags = /Card's options/i.test(r0.eq(0).text());
    const anchorsBefore = precedingAnchors($, table);
    const anchorsInside = r0.eq(0).find('a[name]').toArray().map((a) => $(a));
    const allAnchors = [...anchorsBefore, ...anchorsInside];
    const anchorNames = allAnchors.map((a) => a.attr('name')!).filter(Boolean);
    const semantic = anchorNames.filter((n) => !ID_RE.test(n));

    let display: string;
    let type: string | undefined;
    let options: string[] = [];
    if (flags) {
      const fl = r0.eq(1).find('.flag').toArray().map((f) => squash($(f).text()));
      options = fl;
      display = `Card options: ${fl.join(' | ')}`;
    } else {
      display = squash(r0.eq(0).text());
      type = squash(r0.eq(1).text()) || undefined;
    }

    const meta: { label: string; html: string }[] = [];
    let status: string | undefined;
    let descHtml = '';
    rows.slice(1).each((_, r) => {
      const cells = $(r).children('td');
      const label = squash(cells.eq(0).children('i').first().text()).replace(/:$/, '');
      if (cells.length === 2 && label) {
        if (/^status$/i.test(label)) status = squash(cells.eq(1).text());
        else meta.push({ label, html: (cells.eq(1).html() || '').trim() });
      } else if (cells.length === 1) {
        const c = cells.eq(0);
        const bq = c.children('blockquote');
        descHtml += bq.length === 1 && c.children().length === 1 ? bq.html() || '' : c.html() || '';
      } else {
        warnings.push(`${file}: unrecognised row in variable "${display}": ${squash($(r).text()).slice(0, 80)}`);
        descHtml += `<div>${$(r).html()}</div>`;
      }
    });

    let wanted = semantic[0] ?? slugify(display);
    if (flags && semantic[0]) wanted = semantic[0];
    const id = ids.claim(wanted);
    for (const n of anchorNames) {
      if (aliases[n] && aliases[n] !== id) warnings.push(`${file}: anchor "${n}" used twice`);
      else aliases[n] = id;
    }
    // Build display html: names from the source heading (anchors stripped)
    const nameCell = r0.eq(0).clone();
    nameCell.find('a[name]').each((_, a) => {
      $(a).replaceWith($(a).contents());
    });
    const nameHtml = flags ? `<span class="qe-flags-label">Card options:</span> ${options.map((f) => `<code>${escapeHtml(f)}</code>`).join(' | ')}` : escapeHtml(display);

    const article = buildVarArticle({ id, display, nameHtml, type, status, meta, descHtml, flags });
    anchorsBefore.forEach((a) => a.remove());
    table.replaceWith(article);
    void nameCell;
  }

  /* ---- syntax / description labels ---- */
  main.find('h3').each((_, h) => {
    const label = squash($(h).text()).replace(/:$/, '');
    if (/^(Syntax|Description of items)$/i.test(label)) {
      const next = $(h).next('blockquote');
      const cls = /^Syntax$/i.test(label) ? 'qe-syntax' : 'qe-items';
      if (next.length) next.replaceWith(`<div class="${cls}">${next.html()}</div>`);
      $(h).replaceWith(`<p class="qe-label">${escapeHtml(label)}</p>`);
    }
  });
  main.find('div.syntax').each((_, d) => {
    $(d).attr('class', 'qe-syntax-lines');
  });
  main.find('.qe-syntax table').each((_, t) => {
    $(t).attr('class', 'qe-syntax-table');
  });

  /* ---- conditional boxes (IF / ELSE) ---- */
  const boxes = main.find('table').filter((_, t) => styleHas($(t), '#bb9977')).toArray().reverse();
  for (const t of boxes) {
    const table = $(t);
    const cells = rowsOf($, table).children('td');
    const inner = cells.toArray().map((c) => $(c).html() || '').join('\n');
    const cls = styleHas(table, '#FFddbb') ? 'qe-box qe-branch' : 'qe-box';
    table.replaceWith(`<div class="${cls}">${inner}</div>`);
  }
  main.find('b').each((_, b) => {
    const kw = squash($(b).text()).toUpperCase();
    if (!/^(IF|ELSE ?IF|ELSE)$/.test(kw)) return;
    const el = $(b);
    let cond = '';
    const nx = el.next();
    if (kw !== 'ELSE' && nx.is('code, tt')) {
      cond = nx.html() || '';
      nx.remove();
    }
    const body = el.next('blockquote');
    const bodyHtml = body.length ? body.html() || '' : '';
    body.remove();
    const condHtml = cond ? ` <code class="qe-cond-expr">${cond.replace(/\s*:\s*$/, '')}</code>` : '';
    el.replaceWith(
      `<div class="qe-cond" data-kw="${kw}"><p class="qe-cond-label"><span class="qe-kw">${kw}</span>${condHtml}${cond ? ':' : ''}</p><div class="qe-cond-body">${bodyHtml}</div></div>`,
    );
  });

  /* ---- section header tables (namelists, cards, lines, groups) ---- */
  const sectionTablesDocOrder = main
    .find('table')
    .filter((_, t) => $(t).find('> tbody > tr > th[bgcolor], > tr > th[bgcolor]').length > 0)
    .toArray();
  // claim ids in document order so numbering (line-of-input, line-of-input-2, ...) follows the page
  const preIds = new Map<Element, string>();
  for (const t of sectionTablesDocOrder) {
    const table = $(t);
    const th = rowsOf($, table).eq(0).children('th').first();
    const titleRaw = squash(th.text());
    const semantic = precedingAnchors($, table).map((a) => a.attr('name')!).filter((n) => n && !ID_RE.test(n));
    let name: string | undefined;
    if (/^Namelist:/i.test(titleRaw)) name = squash(th.find('.namelist').text()).replace(/^&/, '');
    else if (/^Card:/i.test(titleRaw)) name = squash(th.find('.card').text());
    const wanted = semantic[0] ?? (name ? name : /^Line of input$/i.test(titleRaw) ? 'line-of-input' : slugify(titleRaw));
    preIds.set(t, ids.claim(wanted));
  }
  const sectionTables = [...sectionTablesDocOrder].reverse();
  for (const t of sectionTables) {
    const table = $(t);
    const rows = rowsOf($, table);
    const th = rows.eq(0).children('th').first();
    const titleRaw = squash(th.text());
    let kind: InputSectionKind = 'group';
    let name: string | undefined;
    let titleHtml = escapeHtml(titleRaw);
    if (/^Namelist:/i.test(titleRaw)) {
      kind = 'namelist';
      name = squash(th.find('.namelist').text()).replace(/^&/, '');
      titleHtml = `<span class="qe-kind">Namelist</span> <span class="qe-nl">&amp;${escapeHtml(name)}</span>`;
    } else if (/^Card:/i.test(titleRaw)) {
      kind = 'card';
      name = squash(th.find('.card').text());
      const flagsTxt = squash(titleRaw.replace(/^Card:\s*/i, '').replace(name, ''));
      titleHtml = `<span class="qe-kind">Card</span> <span class="qe-card">${escapeHtml(name)}</span>${flagsTxt ? ` <span class="qe-card-flags">${escapeHtml(flagsTxt)}</span>` : ''}`;
    } else if (/^Line of input$/i.test(titleRaw)) {
      kind = 'line';
    }
    const anchors = precedingAnchors($, table);
    const anchorNames = anchors.map((a) => a.attr('name')!).filter(Boolean);
    const semantic = anchorNames.filter((n) => !ID_RE.test(n));
    // later rows: content cells, plus closing markers such as END_PATH_INPUT rendered as <th>
    const content = rows
      .slice(1)
      .toArray()
      .map((r) =>
        $(r)
          .children('td, th')
          .toArray()
          .map((c) => (c.tagName === 'th' ? `<p class="qe-section-end"><code>${escapeHtml(squash($(c).text()))}</code></p>` : $(c).html() || ''))
          .join('\n'),
      )
      .join('\n');
    let title = titleRaw;
    if (kind === 'namelist') title = `&${name}`;
    else if (kind === 'card') title = name!;
    const nested = table.parentsUntil(main).filter('table, section, .qe-box').length > 0;
    let wanted = semantic[0] ?? (name ? name : slugify(titleRaw));
    if (kind === 'line') {
      const syn = squash(load(content)('.qe-syntax').first().text());
      if (syn) {
        title = `Line of input: ${syn.length > 60 ? syn.slice(0, 57) + '…' : syn}`;
        titleHtml = `<span class="qe-kind">Line of input</span> <span class="qe-line-syn">${escapeHtml(syn.length > 60 ? syn.slice(0, 57) + '…' : syn)}</span>`;
      }
      wanted = semantic[0] ?? 'line-of-input';
    }
    void wanted;
    const id = preIds.get(t)!;
    anchorNames.forEach((n) => (aliases[n] ??= id));
    anchors.forEach((a) => a.remove());
    const hTag = nested ? 'h3' : 'h2';
    table.replaceWith(
      `<section class="qe-section qe-sec-${kind}" id="${id}" data-kind="${kind}" data-title="${escapeHtml(title)}"${name ? ` data-name="${escapeHtml(name)}"` : ''}>` +
        `<${hTag} class="qe-section-title">${titleHtml}</${hTag}>${content}</section>`,
    );
  }

  /* ---- free-text sections (INTRODUCTION, Notes, ...) ---- */
  main.children('blockquote').each((_, b) => {
    const bq = $(b);
    const h = bq.children('h3').first();
    if (!h.length) return;
    const raw = squash(h.text());
    const title = tidyHeading(raw);
    const anchors = bq.children('a[name]').toArray().map((a) => $(a));
    const anchorNames = anchors.map((a) => a.attr('name')!);
    const id = ids.claim(/^introduction$/i.test(raw) ? 'intro' : slugify(title));
    anchorNames.forEach((n) => (aliases[n] ??= id));
    anchors.forEach((a) => a.remove());
    h.remove();
    const kind: InputSectionKind = /^introduction$/i.test(raw) ? 'intro' : 'text';
    // nested blockquotes with an h3 become subsections
    bq.find('blockquote').each((_, inner) => {
      const ih = $(inner).children('h3').first();
      if (ih.length) {
        const st = tidyHeading(squash(ih.text()));
        const ia = $(inner).children('a[name]').toArray().map((a) => $(a));
        const sid = ids.claim(slugify(st));
        ia.forEach((a) => {
          aliases[a.attr('name')!] ??= sid;
          a.remove();
        });
        ih.replaceWith(`<h3 id="${sid}">${escapeHtml(st)}</h3>`);
      }
    });
    bq.replaceWith(
      `<section class="qe-section qe-sec-${kind}" id="${id}" data-kind="${kind}" data-title="${escapeHtml(title)}"><h2 class="qe-section-title">${escapeHtml(title)}</h2>${bq.html()}</section>`,
    );
  });

  /* ---- stray top-level variables: group them so they are reachable ---- */
  const strays = main.children('article.qe-var');
  if (strays.length) {
    const id = ids.claim('additional-items');
    warnings.push(`${file}: ${strays.length} variable(s) outside any namelist/card in the source: ${strays.toArray().map((a) => $(a).attr('id')).join(', ')}`);
    const first = strays.first();
    const sec = $(`<section class="qe-section qe-sec-group" id="${id}" data-kind="group" data-title="Additional items"><h2 class="qe-section-title">Additional items</h2></section>`);
    first.before(sec);
    strays.each((_, a) => {
      sec.append($(a));
    });
  }

  /* ---- remaining layout tables -> divs (keep syntax tables) ---- */
  const layoutTables = main
    .find('table')
    .filter((_, t) => !$(t).hasClass('qe-syntax-table') && $(t).parents('.qe-syntax').length === 0)
    .toArray()
    .reverse();
  for (const t of layoutTables) {
    const table = $(t);
    const cells = table.find('> tbody > tr > td, > tbody > tr > th, > tr > td, > tr > th');
    table.replaceWith(`<div class="qe-layout">${cells.toArray().map((c) => $(c).html() || '').join('\n')}</div>`);
  }
  main.find('blockquote').each((_, b) => {
    // helpdoc uses blockquote purely for indentation
    $(b).replaceWith(`<div class="qe-indent">${$(b).html()}</div>`);
  });

  return finalizeInputDoc($, main, { ids, aliases, file, docId, program, pkg, version, warnings });
}

export interface FinalizeCtx {
  ids: IdRegistry;
  aliases: Record<string, string>;
  file: string;
  docId: string;
  program: string;
  pkg?: string;
  version?: string;
  warnings: string[];
}

/** Shared tail of the HTML and XML parsers: text flow, anchors, links, sanitising, metadata. */
export function finalizeInputDoc($: CheerioAPI, main: Cheerio<Element>, ctx: FinalizeCtx): ParsedInput {
  const { ids, aliases, file, docId, program, pkg, version, warnings } = ctx;
  /* ---- option lists ---- */
  transformOptionLists($, main);

  /* ---- preformatted text -> flow ---- */
  main.find('pre').each((_, p) => {
    if ($(p).hasClass('qe-pre')) return;
    $(p).replaceWith(flowPre($(p).html() || ''));
  });
  // defaults / meta values: flow their text too
  main.find('.qe-meta dd').each((_, dd) => {
    const h = ($(dd).html() || '').trim();
    if (/\n/.test(h) && !/<(pre|div|p|table)/i.test(h)) $(dd).html(`<span class="qe-flow">${h.replace(/\n\s+/g, '\n')}</span>`);
  });
  // <p> that wrap block content (helpdoc writes <p><pre>...) are fixed by the parser; drop empty paragraphs
  main.find('p').each((_, p) => {
    if (!$(p).text().trim() && !$(p).find('img, br').length) $(p).remove();
  });

  /* ---- remaining anchors -> ids ---- */
  main.find('a[name]').each((_, a) => {
    const n = $(a).attr('name')!;
    const el = $(a);
    if (aliases[n]) {
      if (el.text().trim()) el.replaceWith(el.contents());
      else el.remove();
      return;
    }
    const id = ids.claim(ID_RE.test(n) ? `a-${n}` : n);
    aliases[n] = id;
    if (el.text().trim() && !el.attr('href')) {
      el.replaceWith(`<span id="${id}">${el.html()}</span>`);
    } else if (!el.attr('href')) el.replaceWith(`<span id="${id}" class="qe-anchor"></span>`);
    else el.removeAttr('name').attr('id', id);
  });

  /* ---- links ---- */
  const links: RawLink[] = [];
  main.find('a[href]').each((_, a) => {
    const el = $(a);
    const href = el.attr('href')!.trim();
    const art = el.closest('article.qe-var');
    const fromVar = art.attr('id');
    const kind: 'ref' | 'see' = el.closest('.qe-meta-see').length ? 'see' : 'ref';
    if (el.hasClass('qe-self')) return;
    if (href.startsWith('#')) {
      const frag = decodeURIComponent(href.slice(1));
      const target = aliases[frag] ?? (ids.has(frag) ? frag : undefined);
      if (!target) {
        // broken anchor in the source: identifiers become a search link, anything else is unlinked
        if (/^[A-Za-z_][A-Za-z0-9_]*$/.test(frag)) {
          warnings.push(`${file}: link to missing anchor #${frag} (source) -> search link`);
          el.attr('href', `/search?q=${encodeURIComponent(frag)}`).attr('data-internal', '1').attr('data-broken', '1').attr('title', `"${frag}" is not documented on this page — search all documents`);
        } else {
          warnings.push(`${file}: link to missing anchor #${frag} (source) -> unlinked`);
          el.replaceWith(el.contents());
        }
        return;
      }
      el.attr('href', `#${target}`);
      el.attr('data-local', target);
      links.push({ fromVar, kind, localTarget: target });
      return;
    }
    const xm = href.match(XDOC_RE);
    if (xm) {
      el.attr('data-xdoc', xm[1]);
      if (xm[2]) el.attr('data-xfrag', xm[2]);
      links.push({ fromVar, kind, xdoc: xm[1], xfrag: xm[2] });
    }
  });

  sanitize($, main);
  decorateExternalLinks($, main);

  /* ---- extract metadata from the transformed DOM ---- */
  const sections: InputSection[] = [];
  main.find('section.qe-section').each((_, s) => {
    const sec = $(s);
    const parentSec = sec.parents('section.qe-section').first();
    sections.push({
      id: sec.attr('id')!,
      title: sec.attr('data-title')!,
      kind: sec.attr('data-kind') as InputSectionKind,
      name: sec.attr('data-name'),
      level: sec.parents('section.qe-section').length,
      parent: parentSec.attr('id'),
      // variables whose closest section is this one
      varIds: sec.find('article.qe-var').filter((_, a) => $(a).closest('section.qe-section').attr('id') === sec.attr('id')).toArray().map((a) => $(a).attr('id')!),
    });
  });

  const variables: Variable[] = [];
  const varText: Record<string, string> = {};
  main.find('article.qe-var').each((_, a) => {
    const art = $(a);
    const id = art.attr('id')!;
    const top = art.parents('section.qe-section').last();
    const display = squash(art.find('.qe-var-name').first().text());
    const isFlags = art.hasClass('qe-flags');
    const type = squash(art.find('.qe-var-head .qe-type').text()) || undefined;
    const status = squash(art.find('.qe-var-head .qe-status').text()) || undefined;
    const def = art.find('.qe-meta-default dd').first();
    const descEl = art.find('.qe-desc').first();
    const options = descEl.find('dl.qe-options > div > dt').toArray().map((d) => squash($(d).text()));
    const flagOptions = isFlags ? art.find('.qe-var-name code').toArray().map((c) => squash($(c).text())) : [];
    const descText = blockText(descEl.html() || '');
    const names = deriveNames(display, Object.entries(aliases).filter(([k, v]) => v === id && !ID_RE.test(k)).map(([k]) => k), isFlags);
    variables.push({
      id,
      names,
      display,
      type,
      default: def.length ? squash(def.text()) : undefined,
      status,
      sectionId: top.attr('id') ?? '',
      sectionTitle: top.attr('data-title') ?? '',
      options: isFlags ? flagOptions : options,
      summary: firstSentence(descText),
    });
    varText[id] = [descText, def.length ? `Default: ${squash(def.text())}` : ''].filter(Boolean).join(' ');
  });

  const sectionText: Record<string, string> = {};
  main.find('section.qe-sec-text, section.qe-sec-intro').each((_, s) => {
    sectionText[$(s).attr('id')!] = blockText($(s).html() || '');
  });
  const introText = sectionText['intro'] ?? '';

  const doc: InputDoc = {
    id: docId,
    title: program,
    program,
    package: pkg,
    version,
    html: (main.html() || '').replace(/\n{3,}/g, '\n\n').trim(),
    sections,
    variables,
    aliases,
  };
  return { doc, links, varText, sectionText, introText, warnings };
}

/** Names a variable entry documents, for exact-match search and cross-references. */
export function deriveNames(display: string, semanticAnchors: string[], isFlags: boolean): string[] {
  if (isFlags) return [];
  const out = new Set<string>();
  // identifiers written in the heading, e.g. "x, y, z" or "celldm(i), i=1,6" -> celldm
  const head = display.split(/,\s*(?=[A-Za-z_][\w]*\s*=)/)[0]; // drop ", i=1,ntyp" ranges
  for (const part of head.split(/[,|]/)) {
    const m = part.trim().match(/^([A-Za-z_][A-Za-z0-9_%]*)/);
    if (m && !/^(i|j|k|l|n)$/.test(m[1]) && m[1].length > 0) out.add(m[1]);
  }
  for (const a of semanticAnchors) if (display.includes(a)) out.add(a);
  if (!out.size) for (const a of semanticAnchors) out.add(a);
  return [...out];
}

/** helpdoc renders each option as its own <dl>; merge runs into one list. */
export function transformOptionLists($: CheerioAPI, root: Cheerio<AnyNode>): void {
  root.find('dl').each((_, d) => {
    const dl = $(d);
    if (dl.hasClass('qe-options') || dl.hasClass('qe-meta') || dl.parent().length === 0) return;
    if (dl.closest('dl.qe-meta').length) return;
    const items: string[] = [];
    let node: Cheerio<Element> = dl;
    const run: Cheerio<Element>[] = [];
    while (node.length && node.is('dl') && !node.hasClass('qe-meta')) {
      run.push(node);
      node = node.next() as Cheerio<Element>;
    }
    for (const r of run) {
      r.children('dt').each((_, dt) => {
        const dd = $(dt).next('dd');
        // a <dt> may list several equivalent values: "'gaussian', 'gauss'"
        const label = stripTagsKeep($(dt).html() || '');
        items.push(`<div class="qe-opt"><dt><code>${label}</code></dt><dd>${dd.html() || ''}</dd></div>`);
      });
    }
    const merged = `<dl class="qe-options">${items.join('')}</dl>`;
    run.slice(1).forEach((r) => r.remove());
    run[0].replaceWith(merged);
  });
}

function stripTagsKeep(html: string): string {
  return escapeHtml(stripTags(html).trim().replace(/\s*:$/, ''));
}
